#ifndef GAME_AUTODATA_H
#define GAME_AUTODATA_H

/* Element types for data whose layout is not known yet (src/game/autodata, generated by
 * tools/autodata.py). An object of one of these types is defined in C but still needs
 * its real type: `unk32` was 32-bit words in the disassembly (it may be a struct with
 * narrower fields), `unk16` 16-bit words, `unk8` bytes. `python3 tools/autodata.py report`
 * counts what is left. */
typedef unsigned int unk32;
typedef unsigned short unk16;
typedef unsigned char unk8;

#endif
